import { IMAGE_STYLES, ImageStyle } from "./settings";

/**
 * Style previews — real samples, produced by the real pipeline.
 *
 * A style picker that shows drawings of a style is a promise the generator
 * never made: "Photography" cannot be honestly represented by an illustration.
 * Each preview is therefore generated by the SAME path an article image goes
 * through — same scene, same style directive, same provider — by
 * `scripts/generate-style-previews.ts`, and committed under `public/`.
 *
 * Four assets that never change per customer belong in the build: no bucket,
 * no runtime generation, no way for the picker to be out of sync with what the
 * product renders.
 */

export type PreviewStyle = Exclude<ImageStyle, "custom">;

export const PREVIEW_STYLES = IMAGE_STYLES.map((style) => style.value).filter(
  (value): value is PreviewStyle => value !== "custom"
);

/**
 * One scene, four styles. Holding the subject constant is what makes the
 * difference between the styles legible — the eye compares treatment, not
 * subject matter.
 *
 * Framing and background tone are pinned here because these thumbnails sit
 * side by side on a white card: a pale background makes an image look inset
 * next to a darker one, and four differently-framed subjects read as four
 * different pictures rather than four treatments of one.
 */
export const STYLE_PREVIEW_SCENE =
  "A person sitting at a table reading an open book, head slightly tilted down, calm and focused. Medium shot, the person and the table fill most of the frame. Behind them a plain wall in a clearly visible warm mid-tone colour — never white, never pale, never washed out. The background must read as a distinct colour all the way to the edges of the image";

/** Where the committed sample lives. */
export function stylePreviewSrc(style: PreviewStyle): string {
  return `/style-previews/${style}.jpg`;
}
